52	void exception_handler(void* tf)
53	{
54	  /* XLEN-wide so rv64 mepc/mtval are not truncated and the format is warning-
55	   * free on both ABIs (unsigned long is 32-bit on ilp32, 64-bit on lp64). */
56	  unsigned long mcause, mdcause, mepc, mtval;
57	
58	  asm volatile("csrr %0, mcause" : "=r"(mcause));
59	  asm volatile("csrr %0, mdcause" : "=r"(mdcause));
60	  asm volatile("csrr %0, mepc" : "=r"(mepc));
61	  asm volatile("csrr %0, mtval" : "=r"(mtval));
62	
63	  raw_print_hex("mcause=", mcause);
64	  raw_print_hex("mepc=", mepc);
65	  raw_print_hex("mtval=", mtval);
66	
67	  const unsigned long intbit = 1UL << (__riscv_xlen - 1);  /* mcause MSB */
68	
69	  WRITE_ERROR("Trap occurred!");
70	  WRITE_ERROR("mcause: 0x%lx", mcause);
71	  WRITE_ERROR("mdcause: 0x%lx", mdcause);
72	  WRITE_ERROR("mepc: 0x%lx", mepc);
73	  WRITE_ERROR("mtval: 0x%lx", mtval);
74	  if (tf) {
75	    const unsigned long* regs = (const unsigned long*) tf;
76	    WRITE_ERROR("ra: 0x%lx", regs[1]);
77	    WRITE_ERROR("a0: 0x%lx", regs[10]);
78	  }
79	
80	  if ((mcause & intbit) == 0) {
81	    WRITE_ERROR("Exception code: %lu", mcause);
82	  } else {
83	    WRITE_ERROR("Interrupt occurred! Cause: %lu", mcause & ~intbit);
84	  }
85	
86	  /* _exit() (unlike exit()) does not flush stdio buffers; without this,
87	   * the diagnostic above is silently lost whenever stderr is
88	   * fully-buffered (e.g. not a tty under the vlinux syscall stdio path). */
89	  fflush(stderr);
90	
91	  _exit((int) mcause);
92	}
